import { useEffect, useRef } from 'react';
import { NavLink, useLocation } from 'react-router-dom';

// 页面 chunk 预加载：触摸时提前加载
const PRELOADER: Record<string, () => Promise<unknown>> = {
  '/': () => import('@/pages/DailyPlanPage/DailyPlanPage'),
  '/market': () => import('@/pages/MarketAnalysisPage/MarketAnalysisPage'),
  '/profit': () => import('@/pages/ProfitCalculatorPage/ProfitCalculatorPage'),
  '/ai': () => import('@/pages/AILearningPage/AILearningPage'),
  '/purchase': () => import('@/pages/PurchaseOrderPage/PurchaseOrderPage'),
  '/recipe': () => import('@/pages/RecipePage/RecipePage'),
};

const preloaded = new Set<string>();
function preload(path: string) {
  if (preloaded.has(path)) return;
  const fn = PRELOADER[path];
  if (!fn) return;
  preloaded.add(path);
  fn().catch(() => {});
}
import {
  Calendar,
  TrendingUp,
  Calculator,
  Lightbulb,
  Sparkles,
  Brain,
  Newspaper,
  Flame,
  Package,
} from 'lucide-react';
import type { ThemeConfig } from '@/lib/theme';
import { useShipmentAlert } from '@/hooks/useShipmentAlert';

const NAV_ITEMS = [
  { path: '/', label: '计划', icon: Calendar },
  { path: '/market', label: '市场', icon: TrendingUp },
  { path: '/profit', label: '利润', icon: Calculator },
  { path: '/peak', label: '旺季', icon: Flame },
  { path: '/purchase', label: '采购', icon: Package },
  { path: '/operation', label: '运营', icon: Lightbulb },
  { path: '/viral', label: '爆款', icon: Sparkles },
  { path: '/ai', label: 'AI技巧', icon: Brain },
  { path: '/news', label: '资讯', icon: Newspaper },
];

interface BottomNavProps {
  theme: ThemeConfig;
}

export default function BottomNav({ theme }: BottomNavProps) {
  const { pathname } = useLocation();
  const scrollRef = useRef<HTMLDivElement>(null);
  const { counts, hasShippingDelay } = useShipmentAlert();

  // 切换路由时，将激活项自动滚动到中间位置
  useEffect(() => {
    const container = scrollRef.current;
    const active = container?.querySelector<HTMLElement>('[data-active="true"]');
    if (container && active) {
      const target =
        active.offsetLeft - container.clientWidth / 2 + active.clientWidth / 2;
      container.scrollTo({ left: Math.max(0, target), behavior: 'smooth' });
    }
  }, [pathname]);

  return (
    <nav
      className="fixed bottom-0 left-0 right-0 z-40 md:hidden border-t theme-transition"
      style={{
        paddingBottom: 'env(safe-area-inset-bottom)',
        backgroundColor: `${theme.primary}0A`,
        borderColor: `${theme.primary}12`,
        backdropFilter: 'blur(20px) saturate(200%)',
        WebkitBackdropFilter: 'blur(20px) saturate(200%)',
        boxShadow: `0 -2px 12px ${theme.primary}08`,
      }}
    >
      {/* 顶部 1px 内高光发丝边 */}
      <div
        className="h-px w-full"
        style={{
          background: `linear-gradient(90deg, transparent 0%, rgba(255,255,255,0.6) 50%, transparent 100%)`,
        }}
      />
      <div
        ref={scrollRef}
        className="flex items-center h-16 px-2 overflow-x-auto overflow-y-hidden bottom-nav-scroll"
         style={{
           scrollbarWidth: 'none',
           msOverflowStyle: 'none',
           WebkitOverflowScrolling: 'touch',
         }}
      >
        {NAV_ITEMS.map((item) => {
          const Icon = item.icon;
          const isActive =
            item.path === '/'
              ? pathname === '/'
              : pathname === item.path || pathname.startsWith(item.path + '/');
          const showBadge = item.path === '/purchase' && hasShippingDelay;
          return (
            <NavLink
              key={item.path}
              to={item.path}
              end={item.path === '/'}
              data-active={isActive}
              onMouseEnter={() => preload(item.path)}
              onTouchStart={() => preload(item.path)}
              className="relative flex flex-col items-center justify-center gap-0.5 shrink-0 w-16 py-2"
            >
              {/* 激活态指示点 */}
              {isActive && (
                <span
                  className="absolute top-1 left-1/2 -translate-x-1/2 size-1 rounded-full"
                  style={{ backgroundColor: theme.primary }}
                />
              )}
              <div className="relative">
                <Icon
                  className="size-5 transition-all duration-300 [transition-timing-function:cubic-bezier(0.16,1,0.3,1)]"
                  style={{
                    color: isActive ? theme.primary : undefined,
                    transform: isActive ? 'scale(1.08)' : 'scale(1)',
                  }}
                />
                {showBadge && (
                  <span
                    className="absolute -top-1.5 -right-2.5 min-w-[16px] h-4 px-1 rounded-full text-[10px] font-bold text-white flex items-center justify-center leading-none"
                    style={{ backgroundColor: '#f97316' }}
                  >
                    {counts.shippingDelay > 99 ? '99+' : counts.shippingDelay}
                  </span>
                )}
              </div>
              <span
                className="text-[10px] font-medium whitespace-nowrap transition-all duration-300 [transition-timing-function:cubic-bezier(0.16,1,0.3,1)]"
                style={{
                  color: isActive ? theme.primary : undefined,
                  fontWeight: isActive ? 600 : 500,
                }}
              >
                {item.label}
              </span>
            </NavLink>
          );
        })}
      </div>
      <style>{`
        .bottom-nav-scroll::-webkit-scrollbar {
          display: none;
        }
      `}</style>
    </nav>
  );
}
