import { useEffect, useCallback } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';

/**
 * 全局键盘快捷键：
 * - "/" 聚焦顶部搜索
 * - "g p" 跳转到采购页面
 * - "g l" 跳转到利润测算
 * - "g m" 跳转到市场分析
 * - "g k" 跳转到首页/每日计划
 * - "g n" 跳转到新闻资讯
 * - "g a" 跳转到AI技巧本
 * - "g o" 跳转到运营技巧
 * - "g v" 跳转到爆款二创
 * - "g w" 跳转到天气
 * - "g t" 跳转到团队
 * - "g r" 跳转到菜谱
 */
export function useKeyboardShortcuts({
  onFocusSearch,
}: {
  onFocusSearch?: () => void;
} = {}) {
  const navigate = useNavigate();
  const location = useLocation();

  const handleKeyDown = useCallback(
    (e: KeyboardEvent) => {
      // 在输入框、textarea、contenteditable 中不触发
      const target = e.target as HTMLElement | null;
      if (
        target &&
        (target.tagName === 'INPUT' ||
          target.tagName === 'TEXTAREA' ||
          target.tagName === 'SELECT' ||
          target.isContentEditable)
      ) {
        return;
      }

      // "/" 聚焦搜索
      if (e.key === '/' && !e.metaKey && !e.ctrlKey && !e.altKey) {
        e.preventDefault();
        if (onFocusSearch) {
          onFocusSearch();
        }
        return;
      }

      // "g + 字母" 双键跳转
      if (e.key === 'g' && !e.metaKey && !e.ctrlKey && !e.altKey) {
        e.preventDefault();
        let triggered = false;
        const onSecondKey = (ev: KeyboardEvent) => {
          if (triggered) return;
          triggered = true;
          const key = ev.key.toLowerCase();
          const routes: Record<string, string> = {
            p: '/purchase',
            l: '/profit',
            m: '/market',
            k: '/',
            n: '/news',
            a: '/ai',
            o: '/operation',
            v: '/viral',
            w: '/weather',
            r: '/recipe',
            t: '/team',
            s: '/peak',
            i: '/morning',
          };
          if (routes[key]) {
            ev.preventDefault();
            if (location.pathname !== routes[key]) {
              navigate(routes[key]);
            }
          }
          document.removeEventListener('keydown', onSecondKey);
        };
        document.addEventListener('keydown', onSecondKey);
        setTimeout(() => {
          if (!triggered) {
            document.removeEventListener('keydown', onSecondKey);
          }
        }, 1500);
      }
    },
    [navigate, location.pathname, onFocusSearch]
  );

  useEffect(() => {
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleKeyDown]);
}
