// 页面 chunk 预加载映射：hover/触摸时提前加载，减少点击后等待时间
const PAGE_PRELOADERS: Record<string, () => Promise<unknown>> = {
  '/': () => import('@/pages/DailyPlanPage/DailyPlanPage'),
  '/market': () => import('@/pages/MarketAnalysisPage/MarketAnalysisPage'),
  '/profit': () => import('@/pages/ProfitCalculatorPage/ProfitCalculatorPage'),
  '/peak': () => import('@/pages/PeakSeasonPage/PeakSeasonPage'),
  '/purchase': () => import('@/pages/PurchaseOrderPage/PurchaseOrderPage'),
  '/operation': () => import('@/pages/OperationTipsPage/OperationTipsPage'),
  '/viral': () => import('@/pages/ViralShortsPage/ViralShortsPage'),
  '/ai': () => import('@/pages/AILearningPage/AILearningPage'),
  '/news': () => import('@/pages/NewsPage/NewsPage'),
  '/morning': () => import('@/pages/MarketMorningPage/MarketMorningPage'),
  '/weather': () => import('@/pages/WeatherPage/WeatherPage'),
  '/language': () => import('@/pages/LanguageLearningPage/LanguageLearningPage'),
  '/recipe': () => import('@/pages/RecipePage/RecipePage'),
  '/team': () => import('@/pages/TeamManagementPage/TeamManagementPage'),
};

const preloadedPages = new Set<string>();
function preloadPage(path: string) {
  if (preloadedPages.has(path)) return;
  const loader = PAGE_PRELOADERS[path];
  if (!loader) return;
  preloadedPages.add(path);
  // fire and forget，预加载失败不影响使用
  loader().catch(() => {});
}

