/**
 * 四季主题 SVG 分隔线
 * - 春季：3-4 根细竹 + 小熊猫抱竹
 * - 夏季：2-3 层细海浪 + 冲浪小人剪影（轻盈风格）
 * - 秋季：散落枫叶+银杏叶 + 两个小人剪影
 * - 冬季：细雪花 + 小圣诞树+礼物盒
 * 高度约 18px，左右留边距，整体轻盈精致
 */
function SeasonDivider({ theme }: { theme: ThemeConfig }) {
  const c = theme.primary;
  const cLight = theme.primaryLight;
  const cDark = theme.primaryDark;

  // 渐变：从左到右 浅→深 自然过渡（主体元素用）
  const gradientDef = (
    <defs>
      <linearGradient id="divGrad" x1="0" x2="1" y1="0" y2="0">
        <stop offset="0%" stopColor={cDark} stopOpacity="0.85" />
        <stop offset="50%" stopColor={c} stopOpacity="0.65" />
        <stop offset="100%" stopColor={cLight} stopOpacity="0.4" />
      </linearGradient>
      <linearGradient id="divGradLight" x1="0" x2="1" y1="0" y2="0">
        <stop offset="0%" stopColor={c} stopOpacity="0.45" />
        <stop offset="100%" stopColor={cLight} stopOpacity="0.2" />
      </linearGradient>
      {/* 衰减蒙版：左侧不透明，向右逐渐透明（用于海浪/雪花等的左密右疏效果） */}
      <linearGradient id="fadeMask" x1="0" x2="1" y1="0" y2="0">
        <stop offset="0%" stopColor="white" stopOpacity="1" />
        <stop offset="65%" stopColor="white" stopOpacity="0.7" />
        <stop offset="85%" stopColor="white" stopOpacity="0.2" />
        <stop offset="100%" stopColor="white" stopOpacity="0" />
      </linearGradient>
      {/* 中等衰减蒙版：衰减稍慢 */}
      <linearGradient id="fadeMaskSoft" x1="0" x2="1" y1="0" y2="0">
        <stop offset="0%" stopColor="white" stopOpacity="1" />
        <stop offset="75%" stopColor="white" stopOpacity="0.6" />
        <stop offset="100%" stopColor="white" stopOpacity="0.1" />
      </linearGradient>
    </defs>
  );

  if (theme.season === 'spring') {
    // 春季：左侧竹丛密而高 → 向右逐渐变疏变矮 → 最右侧迷你熊猫
    return (
      <svg
        viewBox="0 0 200 18"
        preserveAspectRatio="none"
        className="w-full h-[18px]"
        aria-hidden="true"
        shapeRendering="geometricPrecision"
      >
        {gradientDef}
        {/* 竹子群（4 根，左密右疏、左高右矮，最右用蒙版淡出） */}
        <g mask="url(#fadeMaskSoft)">
          {[
            { x: 12, top: 1.5, sw: 1.1, op: 0.9 },   // 第1根：最左最高最粗
            { x: 28, top: 3, sw: 1, op: 0.8 },       // 第2根
            { x: 44, top: 5, sw: 0.9, op: 0.7 },     // 第3根：稍矮
            { x: 60, top: 7, sw: 0.8, op: 0.55 },    // 第4根：最矮最淡
          ].map((b, i) => (
            <g
              key={i}
              stroke="url(#divGrad)"
              strokeWidth={b.sw}
              fill="none"
              strokeLinecap="round"
              opacity={b.op}
            >
              {/* 竹杆 */}
              <line x1={b.x} y1={b.top} x2={b.x} y2="17" />
              {/* 竹节（2 个，位置错落） */}
              <line x1={b.x - 1.2} y1={b.top + 4 + i * 0.5} x2={b.x + 1.2} y2={b.top + 4 + i * 0.5} strokeWidth={b.sw * 0.7} />
              <line x1={b.x - 1.2} y1={b.top + 9 + i * 0.5} x2={b.x + 1.2} y2={b.top + 9 + i * 0.5} strokeWidth={b.sw * 0.7} />
              {/* 顶部小竹叶（只在较高的竹子上有） */}
              {i < 3 && (
                <>
                  <path d={`M ${b.x} ${b.top} Q ${b.x + 3} ${b.top - 1} ${b.x + 5} ${b.top + 0.5}`} strokeWidth={b.sw * 0.7} />
                  <path d={`M ${b.x} ${b.top + 1} Q ${b.x - 4} ${b.top} ${b.x - 6} ${b.top + 1.5}`} strokeWidth={b.sw * 0.7} />
                </>
              )}
            </g>
          ))}
        </g>

        {/* 迷你熊猫（最右侧，不受蒙版影响，清晰呈现） */}
        <g transform="translate(170, 4)" strokeLinecap="round" strokeLinejoin="round">
          {/* 抱着的小竹子（细） */}
          <line x1="13" y1="11" x2="18" y2="1" stroke={cDark} strokeWidth="1" />
          <line x1="14" y1="7.5" x2="15.2" y2="6.8" stroke={c} strokeWidth="0.6" />
          {/* 身体（坐姿，圆滚滚，约 10px 高） */}
          <ellipse cx="9" cy="8" rx="4.8" ry="3.5" fill="#fff" stroke={cDark} strokeWidth="0.7" />
          {/* 头 */}
          <circle cx="7.5" cy="4.2" r="2.8" fill="#fff" stroke={cDark} strokeWidth="0.7" />
          {/* 黑耳朵 */}
          <circle cx="5.2" cy="2.2" r="1.1" fill={cDark} />
          <circle cx="9.8" cy="2.2" r="1.1" fill={cDark} />
          {/* 黑眼圈 */}
          <ellipse cx="6.3" cy="4.2" rx="0.85" ry="1" fill={cDark} />
          <ellipse cx="8.7" cy="4.2" rx="0.85" ry="1" fill={cDark} />
          {/* 鼻子+嘴 */}
          <circle cx="7.5" cy="5.3" r="0.4" fill={cDark} />
          <path d="M 7 6 Q 7.5 6.5 8 6" stroke={cDark} strokeWidth="0.4" fill="none" />
          {/* 抱竹子的小爪子 */}
          <ellipse cx="11" cy="6.5" rx="1.2" ry="0.85" fill={cDark} />
        </g>
      </svg>
    );
  }

  if (theme.season === 'summer') {
    // 夏季：左侧浪高而清晰 → 向右逐渐变低变细 → 冲浪板下几乎平息
    // 三层浪都用蒙版实现左高右低、左深右浅的衰减效果
    return (
      <svg
        viewBox="0 0 200 18"
        preserveAspectRatio="none"
        className="w-full h-[18px]"
        aria-hidden="true"
        shapeRendering="geometricPrecision"
      >
        {gradientDef}
        <mask id="waveFade">
          <rect width="200" height="18" fill="url(#fadeMask)" />
        </mask>

        {/* 第 1 层（最上层浪）：左侧波峰最高最清晰，向右逐渐降低消失 */}
        <g mask="url(#waveFade)">
          <path
            d="M 0 6 Q 12 2.5 24 6 T 48 6 T 72 6 T 96 6 T 120 6 T 144 6 T 168 6"
            stroke="url(#divGrad)"
            strokeWidth="1.2"
            fill="none"
            strokeLinecap="round"
            opacity="0.85"
          />
          {/* 浪花小点（只在左半段有，呼应浪峰） */}
          {[15, 39, 63].map((x, i) => (
            <circle
              key={`s1-${i}`}
              cx={x}
              cy={5 - i * 0.3}
              r="0.6"
              fill={cDark}
              opacity={0.6 - i * 0.1}
            />
          ))}
        </g>

        {/* 第 2 层（中层浪）：波峰中等，衰减稍慢 */}
        <g mask="url(#waveFade)">
          <path
            d="M 0 10 Q 18 7 36 10 T 72 10 T 108 10 T 144 10 T 180 10"
            stroke="url(#divGrad)"
            strokeWidth="1"
            fill="none"
            strokeLinecap="round"
            opacity="0.65"
          />
        </g>

        {/* 第 3 层（底层浪）：最平缓，衰减最慢，贴近底部向右延伸更久 */}
        <g mask="url(#waveFade)">
          <path
            d="M 0 13.5 Q 24 11.5 48 13.5 T 96 13.5 T 144 13.5 T 192 13.5"
            stroke="url(#divGradLight)"
            strokeWidth="0.8"
            fill="none"
            strokeLinecap="round"
            opacity="0.55"
          />
        </g>

        {/* 冲浪小人剪影（右侧，清晰呈现，不受蒙版影响） */}
        <g transform="translate(162, 3)" fill={cDark} stroke="none">
          {/* 冲浪板（细长，左端略微抬起踏在浪上） */}
          <ellipse cx="16" cy="12" rx="15" ry="1.1" opacity="0.9" />
          {/* 后腿（弯曲蓄力） */}
          <path d="M 11.5 11 L 10.5 7 L 12 4.5 L 13 7.5 Z" />
          {/* 前腿（支撑站立） */}
          <path d="M 16 11 L 16.5 5 L 17.8 5 L 17.8 11 Z" />
          {/* 身体（前倾姿态） */}
          <path d="M 13.5 4.5 L 17 3 L 18 7 L 14.5 8 Z" />
          {/* 前伸手臂（保持平衡） */}
          <path d="M 16 3.5 L 21.5 2 L 22 3 L 17 4.5 Z" />
          {/* 头 */}
          <circle cx="14.5" cy="1.8" r="1.6" />
        </g>
      </svg>
    );
  }

  if (theme.season === 'autumn') {
    // 秋季：左侧叶密而大 → 向右渐疏渐小 → 最右侧双人剪影
    return (
      <svg
        viewBox="0 0 200 18"
        preserveAspectRatio="none"
        className="w-full h-[18px]"
        aria-hidden="true"
        shapeRendering="geometricPrecision"
      >
        {gradientDef}
        {/* 地面浅光晕（左低右高衰减） */}
        <g mask="url(#fadeMaskSoft)">
          <ellipse cx="60" cy="18" rx="90" ry="3.5" fill="url(#divGradLight)" opacity="0.3" />
        </g>

        {/* 枫叶群（5 片，左密右疏左大右小） */}
        <g mask="url(#fadeMaskSoft)">
          {[
            { x: 12, y: 3, s: 0.75, r: -15, op: 0.8 },
            { x: 30, y: 9, s: 0.65, r: 20, op: 0.7 },
            { x: 52, y: 4, s: 0.6, r: 10, op: 0.6 },
            { x: 75, y: 11, s: 0.5, r: -25, op: 0.5 },
            { x: 98, y: 6, s: 0.45, r: 15, op: 0.4 },
          ].map((leaf, i) => (
            <g
              key={`map-${i}`}
              transform={`translate(${leaf.x}, ${leaf.y}) rotate(${leaf.r}) scale(${leaf.s})`}
              fill="url(#divGrad)"
              opacity={leaf.op}
            >
              <path d="M 0 4.5 L -2 -0.5 L -0.8 0 L -1.5 -3.5 L 0 -1.2 L 1.5 -3.5 L 0.8 0 L 2 -0.5 Z" />
            </g>
          ))}
        </g>

        {/* 银杏叶群（4 片，左大右小） */}
        <g mask="url(#fadeMaskSoft)">
          {[
            { x: 22, y: 13, s: 0.8, op: 0.75 },
            { x: 48, y: 15, s: 0.7, op: 0.65 },
            { x: 75, y: 14, s: 0.6, op: 0.55 },
            { x: 100, y: 15.5, s: 0.5, op: 0.4 },
          ].map((l, i) => (
            <g key={`gink-${i}`} transform={`translate(${l.x}, ${l.y}) scale(${l.s})`} opacity={l.op}>
              <path
                d="M 0 1.5 Q -3 -0.5 -2.5 -4 Q -1 -2.5 0 -4 Q 1 -2.5 2.5 -4 Q 3 -0.5 0 1.5 Z"
                fill="url(#divGradLight)"
                stroke="url(#divGrad)"
                strokeWidth="0.35"
              />
              <line x1="0" y1="1.5" x2="0" y2="3" stroke={cDark} strokeWidth="0.35" />
            </g>
          ))}
        </g>

        {/* 迷你双人剪影（最右侧，清晰呈现） */}
        <g transform="translate(160, 3)" fill={cDark} stroke="none">
          {/* 男生（稍高） */}
          <g>
            <circle cx="5" cy="2" r="1.5" />{/* 头 */}
            <path d="M 3.5 3.5 L 6.5 3.5 L 7.2 11.5 L 2.8 11.5 Z" />{/* 身体 */}
            <rect x="3.2" y="11.5" width="1.4" height="1.8" />{/* 左腿 */}
            <rect x="5.6" y="11.5" width="1.4" height="1.8" />{/* 右腿 */}
            <rect x="6.8" y="5" width="4.5" height="1.1" rx="0.4" />{/* 伸手 */}
          </g>
          {/* 女生（稍矮） */}
          <g transform="translate(12, 2)">
            <circle cx="4" cy="2.2" r="1.3" />{/* 头 */}
            <path d="M 2.2 3.5 L 5.8 3.5 L 7 11 L 1 11 Z" />{/* A字裙 */}
            <rect x="2.2" y="11" width="1.2" height="1.6" />
            <rect x="4.5" y="11" width="1.2" height="1.6" />
            <rect x="-0.8" y="5.5" width="3" height="1" rx="0.4" />{/* 被牵的手 */}
          </g>
        </g>
      </svg>
    );
  }

  // 冬季：左侧雪花密而大 → 向右渐疏渐小 → 最右侧圣诞树+礼物盒
  return (
    <svg
      viewBox="0 0 200 18"
      preserveAspectRatio="none"
      className="w-full h-[18px]"
      aria-hidden="true"
      shapeRendering="geometricPrecision"
    >
      {gradientDef}
      {/* 地面积雪（左低右高衰减，右侧圣诞树前有一块清晰雪地） */}
      <g mask="url(#fadeMaskSoft)">
        <path
          d="M 0 15 Q 40 13.5 80 15 T 160 14.5 L 200 15 L 200 18 L 0 18 Z"
          fill="#fff"
          opacity="0.55"
        />
      </g>
      {/* 右侧圣诞树脚下的一小块清晰雪地（不被蒙版衰减） */}
      <path
        d="M 145 15 Q 175 14.5 200 15 L 200 18 L 145 18 Z"
        fill="#fff"
        opacity="0.7"
      />

      {/* 雪花群（8 片，左密右疏左大右小，用蒙版自然衰减） */}
      <g mask="url(#fadeMask)">
        {[
          { x: 10, y: 2, s: 0.9, op: 0.85 },
          { x: 26, y: 7.5, s: 0.6, op: 0.7 },
          { x: 42, y: 3, s: 0.8, op: 0.78 },
          { x: 58, y: 9, s: 0.55, op: 0.65 },
          { x: 76, y: 3.5, s: 0.7, op: 0.68 },
          { x: 94, y: 10, s: 0.5, op: 0.55 },
          { x: 112, y: 5, s: 0.6, op: 0.5 },
          { x: 130, y: 11, s: 0.4, op: 0.35 },
        ].map((s, i) => (
          <g
            key={i}
            transform={`translate(${s.x}, ${s.y}) scale(${s.s})`}
            stroke="url(#divGrad)"
            strokeWidth="0.6"
            strokeLinecap="round"
            fill="none"
            opacity={s.op}
          >
            {/* 简单六角雪花 */}
            <line x1="0" y1="-2.5" x2="0" y2="2.5" />
            <line x1="-2.2" y1="-1.2" x2="2.2" y2="1.2" />
            <line x1="-2.2" y1="1.2" x2="2.2" y2="-1.2" />
          </g>
        ))}
      </g>

      {/* 小礼物盒 1（右侧） */}
      <g transform="translate(148, 9)">
        <rect x="0" y="4" width="6" height="4" fill="url(#divGrad)" rx="0.4" />
        <rect x="2.6" y="4" width="0.8" height="4" fill="#fff" opacity="0.75" />
        <rect x="0" y="5.2" width="6" height="0.8" fill="#fff" opacity="0.75" />
        <circle cx="3" cy="3.6" r="0.7" fill={cDark} />
      </g>

      {/* 小礼物盒 2（更小，前面） */}
      <g transform="translate(156, 11)">
        <rect x="0" y="3" width="4.5" height="3" fill="url(#divGradLight)" rx="0.3" />
        <rect x="2" y="3" width="0.5" height="3" fill="#fff" opacity="0.6" />
        <rect x="0" y="3.8" width="4.5" height="0.5" fill="#fff" opacity="0.6" />
      </g>

      {/* 迷你圣诞树（最右侧，清晰呈现） */}
      <g transform="translate(170, 2)" strokeLinejoin="round">
        {/* 树冠 3 层 */}
        <polygon points="6,1.5 2.5,6.5 9.5,6.5" fill="url(#divGrad)" stroke={cDark} strokeWidth="0.4" />
        <polygon points="6,5 2,10 10,10" fill="url(#divGrad)" stroke={cDark} strokeWidth="0.4" opacity="0.85" />
        <polygon points="6,8 3,14 9,14" fill="url(#divGrad)" stroke={cDark} strokeWidth="0.4" opacity="0.7" />
        {/* 树干 */}
        <rect x="5.2" y="14" width="1.6" height="1.5" fill="#8B4513" />
        {/* 顶星 */}
        <polygon
          points="6,0 6.5,1 7.5,1.1 6.8,1.8 7,2.8 6,2.3 5,2.8 5.2,1.8 4.5,1.1 5.5,1"
          fill="#FFD700"
          stroke="#FFA500"
          strokeWidth="0.25"
        />
        {/* 彩球装饰 */}
        <circle cx="3.8" cy="7" r="0.45" fill="#FF6B6B" />
        <circle cx="7.8" cy="9" r="0.45" fill="#FFD93D" />
        <circle cx="5" cy="12" r="0.4" fill={cLight} />
      </g>
    </svg>
  );
}

export default function AppSidebar({ theme, festival, isOpen, onClose }: AppSidebarProps) {
  const { pathname } = useLocation();
  const { counts } = useShipmentAlert();
  const { recent } = useRecentModules();

  // 从导航配置里找 icon
  const iconMap = new Map<string, ComponentType<{ className?: string }>>();
  NAV_GROUPS.forEach((g) => g.items.forEach((i) => iconMap.set(i.path, i.icon)));

  function renderNavItem(item: NavItem) {
    const Icon = item.icon;
    const isActive =
      item.path === '/'
        ? pathname === '/'
        : pathname === item.path || pathname.startsWith(item.path + '/');
    // 仅售后动态菜单显示异常徽标（总异常数）
    const showBadge = item.path === '/purchase' && counts.total > 0;
    return (
      <NavLink
        key={item.path}
        to={item.path}
        end={item.path === '/'}
        onClick={onClose}
        onMouseEnter={() => preloadPage(item.path)}
        onTouchStart={() => preloadPage(item.path)}
        onFocus={() => preloadPage(item.path)}
         className={`
           relative flex items-center gap-2.5 px-2.5 py-2 rounded-md text-[13px] font-medium
           transition-all duration-300 ease-out
           ${isActive
             ? ''
             : 'text-foreground/65 hover:bg-white/60 hover:text-foreground'
           }
         `}
         style={{
           color: isActive ? theme.primary : undefined,
           backgroundColor: isActive ? `${theme.primary}10` : undefined,
           fontWeight: isActive ? 600 : 500,
         }}
       >
          {/* 左侧指示条 */}
          <span
            className={`
              absolute left-0 top-1/2 -translate-y-1/2 w-0.5 rounded-r-full
              transition-all duration-300 ease-out
              ${isActive ? 'h-4 opacity-100' : 'h-0 opacity-0'}
            `}
            style={{ backgroundColor: theme.primary }}
          />
          {/* 底部倾斜下划线 */}
          <span
            className={`
              absolute bottom-1 left-3 right-3 h-[3px] rounded-[2px]
              transition-all duration-300 ease-out -skew-x-[8deg]
              ${isActive ? 'opacity-100 scale-x-100' : 'opacity-0 scale-x-0'}
            `}
            style={{ backgroundColor: theme.primary }}
          />
         <div className="relative shrink-0">
           <Icon className="size-4" />
           {showBadge && (
              <span
                className="absolute -top-1.5 -right-2.5 min-w-[16px] h-4 px-1 rounded-full text-[10px] font-bold text-white flex items-center justify-center leading-none"
                style={{ backgroundColor: '#ef4444' }}
              >
                {counts.total > 99 ? '99+' : counts.total}
              </span>
           )}
         </div>
         <span className="truncate flex-1">{item.label}</span>
      </NavLink>
    );
  }

  return (
    <>
      {/* Mobile overlay */}
      {isOpen && (
        <div
          className="fixed inset-0 bg-black/40 z-40 md:hidden"
          onClick={onClose}
        />
      )}

      <aside
        className={`
          fixed top-0 left-0 z-50 h-full w-52 shrink-0
          flex flex-col
          bg-gradient-to-b ${theme.sidebarBg}
          border-r border-white/40 backdrop-blur-sm
          shadow-lg
          transform transition-transform duration-300 ease-out
          ${isOpen ? 'translate-x-0' : '-translate-x-full'}
          md:translate-x-0 md:static
        `}
      >
        {/* Header */}
        <div className="shrink-0 px-4 py-4 border-b border-white/50">
          <div className="flex items-center gap-2">
            <Image
              src={resolveAppUrl('/assets/logo-256.png')}
              alt="鑫之海"
              className="size-8 shrink-0 rounded-md object-contain"
            />
            <div className="flex-1 min-w-0">
              <div className="text-sm font-bold" style={{ color: theme.primary }}>
                鑫之海
              </div>
              <div className="text-xs text-muted-foreground">
                {theme.name}主题
              </div>
            </div>
            <span className="text-lg">{theme.decorIcon2}</span>
          </div>
          {festival.active && (
            <div
              className={`mt-3 px-3 py-1.5 rounded-lg text-xs font-medium text-center ${festival.textColor || ''}`}
              style={{
                backgroundColor: festival.textColor ? 'transparent' : theme.primaryLight + '30',
                border: festival.textColor ? `1px solid ${theme.primary}` : 'none',
              }}
            >
              {festival.icon && <span className="mr-1">{festival.icon}</span>}
              {festival.text || festival.name}
            </div>
          )}
        </div>

        {/* Nav Items - flex-1 占满剩余空间，超出滚动 */}
         <nav className="flex-1 px-2 py-3 space-y-3 overflow-y-auto min-h-0">
          {/* 最近使用 */}
          {recent.length > 0 && (
            <div className="space-y-1 mb-2">
              <div
                className="px-2.5 pb-1 text-[10px] font-semibold tracking-[0.08em] uppercase opacity-40 flex items-center gap-1"
                style={{ color: theme.primaryDark }}
              >
                <Clock className="size-3" />
                最近使用
              </div>
              <div className="space-y-0.5">
                {recent.map((m) => {
                  const Icon = iconMap.get(m.path) || Zap;
                  const isActive =
                    m.path === '/'
                      ? pathname === '/'
                      : pathname === m.path || pathname.startsWith(m.path + '/');
                  return (
                    <NavLink
                      key={m.path}
                      to={m.path}
                      end={m.path === '/'}
                      onClick={onClose}
                      onMouseEnter={() => preloadPage(m.path)}
                      onTouchStart={() => preloadPage(m.path)}
                      className={`
                        relative flex items-center gap-2 px-2.5 py-1.5 rounded-md text-[12px] font-medium
                        transition-all duration-200 ease-out
                        ${isActive ? '' : 'text-foreground/60 hover:bg-white/50 hover:text-foreground'}
                      `}
                      style={{
                        color: isActive ? theme.primary : undefined,
                        backgroundColor: isActive ? `${theme.primary}10` : undefined,
                      }}
                    >
                      <Icon className="size-3.5 shrink-0" />
                      <span className="truncate flex-1">{m.label}</span>
                      {/* 底部倾斜下划线 */}
                      <span
                        className={`
                          absolute bottom-0.5 left-3 right-3 h-[2px] rounded-[1px]
                          transition-all duration-200 ease-out -skew-x-[8deg]
                          ${isActive ? 'opacity-100 scale-x-100' : 'opacity-0 scale-x-0'}
                        `}
                        style={{ backgroundColor: theme.primary }}
                      />
                    </NavLink>
                  );
                })}
              </div>
            </div>
          )}

          {NAV_GROUPS.map((group, groupIdx) => (
            <div key={group.title} className="space-y-1">
               {/* 分组标题 */}
               <div
                 className="px-2.5 pb-1 text-[10px] font-semibold tracking-[0.08em] uppercase opacity-40"
                 style={{ color: theme.primaryDark }}
               >
                {group.title}
              </div>

              {/* 该组导航项 */}
              <div className="space-y-0.5">
                {group.items.map(renderNavItem)}
              </div>

               {/* 两组之间的四季分隔线（只在第一组下方显示） */}
               {groupIdx === 0 && (
                 <div className="pt-1.5 pb-0.5 flex items-center justify-center px-1">
                  <SeasonDivider theme={theme} />
                </div>
              )}
            </div>
          ))}
        </nav>

        {/* Footer - 跟在导航下方，不遮挡菜单项 */}
         <div className="shrink-0 p-3 pt-2 border-t border-white/50">
           <div className="text-xs text-muted-foreground text-center">
             {theme.decorIcon1} 今日也要加油 {theme.decorIcon2}
           </div>
         </div>
      </aside>
    </>
  );
}
