import { useState, useEffect, useCallback } from 'react';
import { scopedStorage } from '@lark-apaas/client-toolkit-lite';

const STORAGE_KEY = 'recent_modules_v1';
const MAX_RECENT = 3;

export interface RecentModule {
  path: string;
  label: string;
  visitedAt: number;
}

function loadRecent(): RecentModule[] {
  try {
    const raw = scopedStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const arr = JSON.parse(raw);
    if (Array.isArray(arr)) return arr.slice(0, MAX_RECENT);
    return [];
  } catch {
    return [];
  }
}

function saveRecent(list: RecentModule[]) {
  try {
    scopedStorage.setItem(STORAGE_KEY, JSON.stringify(list.slice(0, MAX_RECENT)));
  } catch {
    /* noop */
  }
}

export function useRecentModules() {
  const [recent, setRecent] = useState<RecentModule[]>(() => loadRecent());

  const recordVisit = useCallback((path: string, label: string) => {
    setRecent((prev) => {
      // 去掉相同路径的旧记录
      const filtered = prev.filter((m) => m.path !== path);
      const next = [{ path, label, visitedAt: Date.now() }, ...filtered].slice(0, MAX_RECENT);
      saveRecent(next);
      return next;
    });
  }, []);

  const clearRecent = useCallback(() => {
    setRecent([]);
    try {
      scopedStorage.removeItem(STORAGE_KEY);
    } catch {
      /* noop */
    }
  }, []);

  return { recent, recordVisit, clearRecent };
}
