import { useState, useEffect, useCallback, useMemo } from 'react';
import { scopedStorage, logger } from '@lark-apaas/client-toolkit-lite';

// ==================== 类型定义 ====================

type AbnormalType =
  | 'shipping_delay'
  | 'arrival_damaged'
  | 'arrival_defective'
  | 'quantity_missing';

export interface AbnormalCounts {
  total: number;
  shippingDelay: number;
  damaged: number;
  defective: number;
  missing: number;
  cross20d: number;
  cross25d: number;
  cross30d: number;
  cross35d: number;
  crossTotal: number;
}

// ==================== 采购单精简类型（从采购页提取核心字段） ====================

type OrderStatus =
  | 'ordered'
  | 'pending_ship'
  | 'shipped'
  | 'in_transit'
  | 'arrived'
  | 'warehoused'
  | 'cancelled';

interface PurchaseOrderLite {
  id: string;
  status: OrderStatus;
  shippedAt?: string;
  updatedAt?: string;
  createdAt?: string;
  expressTimeline?: string;
  arrivalQuality?: 'normal' | 'damaged' | 'defective' | 'missing';
}

// ==================== 常量 ====================

const ORDERS_STORAGE_KEY = 'purchase_orders_v2';
const LEADTIME_STORAGE_KEY = 'purchase-leadtime-records';
const READ_ALERT_KEY = 'shipment_alert_read_ids';

// ==================== 异常检测逻辑（与采购页保持一致） ====================

function extractExpectedDays(text: string): number | null {
  const match = text.match(/(\d+)\s*天/);
  if (match) return parseInt(match[1], 10);
  const rangeMatch = text.match(/(\d+)\s*[-~～]\s*(\d+)\s*天/);
  if (rangeMatch) return parseInt(rangeMatch[2], 10);
  return null;
}

function getShippingDays(order: PurchaseOrderLite): number | null {
  const baseTime = order.shippedAt || order.updatedAt || order.createdAt;
  if (!baseTime) return null;
  const start = new Date(baseTime).getTime();
  const now = Date.now();
  const diffDays = (now - start) / (1000 * 60 * 60 * 24);
  return Math.floor(diffDays);
}

function detectAbnormalCounts(orders: PurchaseOrderLite[]): AbnormalCounts {
  let shippingDelay = 0;
  let damaged = 0;
  let defective = 0;
  let missing = 0;

  const arrivedOrWarehoused = (s: OrderStatus) =>
    s === 'arrived' || s === 'warehoused';

  orders.forEach((order) => {
    // 运输超 7 天
    if (order.status === 'shipped' || order.status === 'in_transit') {
      const days = getShippingDays(order);
      const expectedDays = order.expressTimeline
        ? extractExpectedDays(order.expressTimeline)
        : null;
      const isOverdue =
        (days !== null && days > 7) ||
        (expectedDays !== null && expectedDays > 7);
      if (isOverdue) shippingDelay++;
    }

    // 到库破损
    if (arrivedOrWarehoused(order.status) && order.arrivalQuality === 'damaged') {
      damaged++;
    }

    // 到库瑕疵
    if (arrivedOrWarehoused(order.status) && order.arrivalQuality === 'defective') {
      defective++;
    }

    // 数量漏件
    if (arrivedOrWarehoused(order.status) && order.arrivalQuality === 'missing') {
      missing++;
    }
  });

  return {
    total: shippingDelay + damaged + defective + missing,
    shippingDelay,
    damaged,
    defective,
    missing,
    cross20d: 0,
    cross25d: 0,
    cross30d: 0,
    cross35d: 0,
    crossTotal: 0,
  };
}

// ==================== 从本地存储加载订单 ====================

function loadOrdersFromStorage(): PurchaseOrderLite[] {
  try {
    const raw = scopedStorage.getItem(ORDERS_STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (Array.isArray(parsed)) return parsed as PurchaseOrderLite[];
    return [];
  } catch (e) {
    logger.warn('加载采购订单失败:', String(e));
    return [];
  }
}

function loadLeadTimeFromStorage(): Array<{ orderedAt: string; arrivedAt?: string; status?: string; arrivalQuality?: string }> {
  try {
    const raw = scopedStorage.getItem(LEADTIME_STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (Array.isArray(parsed)) return parsed;
    return [];
  } catch (e) {
    logger.warn('加载时效记录失败:', String(e));
    return [];
  }
}

function detectCrossBorderCounts(records: Array<{ orderedAt: string; arrivedAt?: string; status?: string; arrivalQuality?: string }>) {
  let cross20d = 0;
  let cross25d = 0;
  let cross30d = 0;
  let cross35d = 0;

  records.forEach((r) => {
    if (r.arrivedAt || r.status === 'arrived' || r.status === 'warehoused') return;
    const t = new Date(r.orderedAt).getTime();
    if (isNaN(t)) return;
    const days = Math.floor((Date.now() - t) / (1000 * 60 * 60 * 24));
    if (days >= 35) cross35d++;
    else if (days >= 30) cross30d++;
    else if (days >= 25) cross25d++;
    else if (days >= 20) cross20d++;
  });

  const crossTotal = cross20d + cross25d + cross30d + cross35d;
  return { cross20d, cross25d, cross30d, cross35d, crossTotal };
}

// ==================== 已读状态管理 ====================

interface ReadAlertState {
  // 已读的异常数量签名：当数量变化时重新提醒
  lastKnownCount: number;
  // 已读时间戳
  lastReadAt: number;
}

function loadReadState(): ReadAlertState {
  try {
    const raw = scopedStorage.getItem(READ_ALERT_KEY);
    if (!raw) return { lastKnownCount: 0, lastReadAt: 0 };
    return JSON.parse(raw);
  } catch {
    return { lastKnownCount: 0, lastReadAt: 0 };
  }
}

function saveReadState(state: ReadAlertState) {
  try {
    scopedStorage.setItem(READ_ALERT_KEY, JSON.stringify(state));
  } catch (e) {
    logger.warn('保存提醒已读状态失败:', String(e));
  }
}

// ==================== Hook ====================

export function useShipmentAlert() {
  const [counts, setCounts] = useState<AbnormalCounts>({
    total: 0,
    shippingDelay: 0,
    damaged: 0,
    defective: 0,
    missing: 0,
    cross20d: 0,
    cross25d: 0,
    cross30d: 0,
    cross35d: 0,
    crossTotal: 0,
  });
  const [bannerVisible, setBannerVisible] = useState(false);

  // 重新检测异常
  const refresh = useCallback(() => {
    const orders = loadOrdersFromStorage();
    const domestic = detectAbnormalCounts(orders);
    const leadTime = loadLeadTimeFromStorage();
    const cross = detectCrossBorderCounts(leadTime);

    const newCounts: AbnormalCounts = {
      total: domestic.total + cross.crossTotal,
      shippingDelay: domestic.shippingDelay,
      damaged: domestic.damaged,
      defective: domestic.defective,
      missing: domestic.missing,
      cross20d: cross.cross20d,
      cross25d: cross.cross25d,
      cross30d: cross.cross30d,
      cross35d: cross.cross35d,
      crossTotal: cross.crossTotal,
    };
    setCounts(newCounts);

    // 判断是否需要显示横幅：有运输超7天 或 跨境超20天 异常
    if (newCounts.shippingDelay > 0 || newCounts.crossTotal > 0) {
      const readState = loadReadState();
      if (
        newCounts.total > readState.lastKnownCount ||
        (readState.lastKnownCount === 0 && readState.lastReadAt === 0)
      ) {
        setBannerVisible(true);
      }
    } else {
      setBannerVisible(false);
    }
  }, []);

  // 标记为已读（关闭横幅时调用，但红点保留）
  const markAsRead = useCallback(() => {
    saveReadState({
      lastKnownCount: counts.total,
      lastReadAt: Date.now(),
    });
    setBannerVisible(false);
  }, [counts.total]);

  // 应用启动时首次检测
  useEffect(() => {
    refresh();
  }, [refresh]);

  // 从后台切回前台时重新检测
  useEffect(() => {
    const handleVisibility = () => {
      if (document.visibilityState === 'visible') {
        refresh();
      }
    };
    document.addEventListener('visibilitychange', handleVisibility);
    return () => document.removeEventListener('visibilitychange', handleVisibility);
  }, [refresh]);

  // 监听 storage 事件（多标签页同步）
  useEffect(() => {
    const handleStorage = (e: StorageEvent) => {
      if (e.key && e.key.includes(ORDERS_STORAGE_KEY)) {
        refresh();
      }
    };
    window.addEventListener('storage', handleStorage);
    return () => window.removeEventListener('storage', handleStorage);
  }, [refresh]);

  // 轮询检测（订单可能在其他页面被修改）
  // 页面后台时暂停，前台恢复，减少不必要的资源占用
  useEffect(() => {
    let timer: ReturnType<typeof setInterval> | null = null;

    function startPolling() {
      if (timer) return;
      timer = setInterval(refresh, 30000);
    }

    function stopPolling() {
      if (timer) {
        clearInterval(timer);
        timer = null;
      }
    }

    function handleVisibility() {
      if (document.visibilityState === 'visible') {
        // 回到前台先立刻刷一次，再启动轮询
        refresh();
        startPolling();
      } else {
        stopPolling();
      }
    }

    // 初始启动（仅前台时启动）
    if (typeof document !== 'undefined' && document.visibilityState === 'visible') {
      startPolling();
    }

    document.addEventListener('visibilitychange', handleVisibility);
    return () => {
      document.removeEventListener('visibilitychange', handleVisibility);
      stopPolling();
    };
  }, [refresh]);

  const hasAbnormal = counts.total > 0;

  return useMemo(
    () => ({
      counts,
      hasAbnormal,
      hasShippingDelay: hasAbnormal,
      bannerVisible,
      setBannerVisible,
      markAsRead,
      refresh,
    }),
    [counts, hasAbnormal, bannerVisible, markAsRead, refresh],
  );
}

// 导出类型供其他文件使用
export type { AbnormalType };
