import { lazy, type ComponentType } from 'react';
import { Routes, Route, Navigate } from 'react-router-dom';
import { Layout } from '@/components/Layout';
import NotFoundPage from '@/pages/NotFoundPage/NotFoundPage';
import { withLazyPage } from '@/components/LazyRouteWrapper';

const DailyPlanPage = lazy(() => import('@/pages/DailyPlanPage/DailyPlanPage'));
const MarketAnalysisPage = lazy(() => import('@/pages/MarketAnalysisPage/MarketAnalysisPage'));
const ProfitCalculatorPage = lazy(() => import('@/pages/ProfitCalculatorPage/ProfitCalculatorPage'));
const PeakSeasonPage = lazy(() => import('@/pages/PeakSeasonPage/PeakSeasonPage'));
const LanguageLearningPage = lazy(() => import('@/pages/LanguageLearningPage/LanguageLearningPage'));
const OperationTipsPage = lazy(() => import('@/pages/OperationTipsPage/OperationTipsPage'));
const RecipePage = lazy(() => import('@/pages/RecipePage/RecipePage'));
const ViralShortsPage = lazy(() => import('@/pages/ViralShortsPage/ViralShortsPage'));
const AILearningPage = lazy(() => import('@/pages/AILearningPage/AILearningPage'));
const NewsPage = lazy(() => import('@/pages/NewsPage/NewsPage'));
const MarketMorningPage = lazy(() => import('@/pages/MarketMorningPage/MarketMorningPage'));
const WeatherPage = lazy(() => import('@/pages/WeatherPage/WeatherPage'));
const TeamManagementPage = lazy(() => import('@/pages/TeamManagementPage/TeamManagementPage'));
const PurchaseOrderPage = lazy(() => import('@/pages/PurchaseOrderPage/PurchaseOrderPage'));

export default function App() {
  return (
    <Routes>
      <Route element={<Layout />}>
        <Route index element={withLazyPage(DailyPlanPage)} />
        <Route path="market" element={withLazyPage(MarketAnalysisPage)} />
        <Route path="profit" element={withLazyPage(ProfitCalculatorPage)} />
        <Route path="peak" element={withLazyPage(PeakSeasonPage)} />
        <Route path="language" element={withLazyPage(LanguageLearningPage)} />
        <Route path="operation" element={withLazyPage(OperationTipsPage)} />
        <Route path="recipe" element={withLazyPage(RecipePage)} />
        <Route path="viral" element={withLazyPage(ViralShortsPage)} />
        <Route path="ai" element={withLazyPage(AILearningPage)} />
        <Route path="news" element={withLazyPage(NewsPage)} />
        <Route path="morning" element={withLazyPage(MarketMorningPage)} />
        <Route path="weather" element={withLazyPage(WeatherPage)} />
        <Route path="team" element={withLazyPage(TeamManagementPage)} />
        <Route path="purchase" element={withLazyPage(PurchaseOrderPage)} />
        {/* 旧 KPI 路由：重定向到首页（KPI 已并入每日巡店） */}
        <Route path="kpi" element={<Navigate to="/" replace />} />
      </Route>
      <Route path="*" element={<NotFoundPage />} />
    </Routes>
  );
}
