import { useNavigate } from 'react-router-dom';
import { X, CalendarClock, ChevronRight } from 'lucide-react';
import type { AbnormalCounts } from '@/hooks/useShipmentAlert';

interface ShipmentAlertBannerProps {
  counts: AbnormalCounts;
  onClose: () => void;
}

export default function ShipmentAlertBanner({
  counts,
  onClose,
}: ShipmentAlertBannerProps) {
  const navigate = useNavigate();

  const handleClick = () => {
    // 跳转到采购页，并带上 hash 定位到运输超7天筛选
    navigate('/purchase#shipping_delay');
    onClose();
  };

  if (counts.shippingDelay === 0) return null;

  return (
    <div
      className="relative overflow-hidden border-b"
      style={{
        background:
          'linear-gradient(90deg, rgba(251,146,60,0.12) 0%, rgba(245,158,11,0.08) 50%, rgba(251,146,60,0.12) 100%)',
        borderColor: 'rgba(251,146,60,0.25)',
      }}
    >
      {/* 背景装饰：左侧橙色光晕 */}
      <div
        className="absolute -left-16 top-1/2 -translate-y-1/2 size-32 rounded-full blur-3xl opacity-30"
        style={{ backgroundColor: '#f97316' }}
        aria-hidden="true"
      />

      <div className="relative px-4 py-3 md:px-6 flex items-center gap-3 max-w-6xl mx-auto">
        {/* 左侧图标 */}
        <div
          className="size-9 rounded-lg flex items-center justify-center shrink-0"
          style={{ backgroundColor: 'rgba(251,146,60,0.18)' }}
        >
          <CalendarClock className="size-5 text-orange-500" />
        </div>

        {/* 文字内容 */}
        <button
          onClick={handleClick}
          className="flex-1 min-w-0 text-left flex items-center gap-2 group"
        >
          <div className="min-w-0">
            <div className="text-sm font-semibold text-foreground flex items-center gap-2">
              <span className="text-orange-600">
                有 {counts.shippingDelay} 笔运输超 7 天
              </span>
              <span className="text-muted-foreground font-normal">，请及时处理</span>
            </div>
            <div className="text-xs text-muted-foreground mt-0.5">
              {counts.total > counts.shippingDelay &&
                `另有 ${counts.total - counts.shippingDelay} 条其他异常待跟进 · `}
              点击查看详情并一键处理
            </div>
          </div>
          <ChevronRight className="size-4 text-muted-foreground shrink-0 opacity-60 group-hover:opacity-100 group-hover:translate-x-0.5 transition-all" />
        </button>

        {/* 关闭按钮 */}
        <button
          onClick={onClose}
          className="size-7 rounded-md flex items-center justify-center text-muted-foreground hover:bg-black/5 hover:text-foreground transition-colors shrink-0"
          aria-label="关闭提醒"
        >
          <X className="size-4" />
        </button>
      </div>
    </div>
  );
}
