import { useState, useEffect, type ComponentType, Suspense } from 'react';
import { ErrorBoundary } from 'react-error-boundary';
import { logger } from '@lark-apaas/client-toolkit-lite';
import { useLocation } from 'react-router-dom';

function PageFallback({ timeout }: { timeout: boolean }) {
  return (
    <div className="space-y-3 py-2">
      {/* Header 骨架 */}
      <div className="rounded-xl border border-border/60 bg-card p-5 shadow-sm animate-pulse">
        <div className="h-6 w-32 bg-muted/70 rounded mb-2" />
        <div className="h-4 w-48 bg-muted/50 rounded" />
      </div>
      {/* 列表/卡片骨架 */}
      {[0, 1, 2, 3, 4].map((i) => (
        <div
          key={i}
          className="rounded-xl border border-border/60 bg-card p-4 shadow-sm animate-pulse"
          style={{ animationDelay: `${i * 80}ms` }}
        >
          <div className="flex gap-3">
            <div className="size-12 bg-muted/60 rounded-lg shrink-0 hidden sm:block" />
            <div className="flex-1 min-w-0 space-y-2">
              <div className="h-5 w-3/4 bg-muted/60 rounded" />
              <div className="h-4 w-full bg-muted/40 rounded" />
              <div className="h-4 w-2/3 bg-muted/40 rounded" />
            </div>
          </div>
        </div>
      ))}
      {timeout && (
        <p className="text-center text-sm text-muted-foreground pt-2">
          网络较慢，正在努力加载...请检查网络连接
        </p>
      )}
    </div>
  );
}

function PageErrorFallback({
  error,
  resetErrorBoundary,
}: {
  error: Error;
  resetErrorBoundary: () => void;
}) {
  return (
    <div className="py-16 flex flex-col items-center justify-center text-center">
      <div className="size-16 rounded-full bg-muted flex items-center justify-center mb-4">
        <span className="text-3xl">⚠️</span>
      </div>
      <h3 className="text-base font-semibold mb-1 text-foreground">本页加载失败</h3>
      <p className="text-sm text-muted-foreground mb-4 max-w-md px-4">
        {error?.message || '发生了未知错误，请尝试重试'}
      </p>
      <p className="text-xs text-muted-foreground mb-4">
        你仍可使用左侧菜单或底部导航切换其它模块
      </p>
      <div className="flex gap-2">
        <button
          onClick={resetErrorBoundary}
          className="px-4 py-2 rounded-md bg-primary text-primary-foreground text-sm font-medium hover:opacity-90 active:scale-95 transition-all"
        >
          重试
        </button>
        <button
          onClick={() => window.location.reload()}
          className="px-4 py-2 rounded-md border border-border text-foreground text-sm font-medium hover:bg-muted active:scale-95 transition-all"
        >
          刷新页面
        </button>
      </div>
    </div>
  );
}

/**
 * 带超时的 Suspense：10秒没加载出来提示网络慢
 */
function TimedSuspense({ children }: { children: React.ReactNode }) {
  const [timeout, setTimeout] = useState(false);
  const location = useLocation();

  useEffect(() => {
    setTimeout(false);
    const timer = window.setTimeout(() => setTimeout(true), 10000);
    return () => window.clearTimeout(timer);
  }, [location.pathname]);

  return <Suspense fallback={<PageFallback timeout={timeout} />}>{children}</Suspense>;
}

/**
 * 懒加载页面包装器：
 * - Suspense + 10秒超时提示
 * - ErrorBoundary 页面级兜底
 * - 路由切换淡入过渡（CSS 动画，避免引入 framer-motion 进主 bundle）
 */
export default function LazyRouteWrapper({ children }: { children: React.ReactNode }) {
  const location = useLocation();
  const [retryKey, setRetryKey] = useState(0);
  const [animateKey, setAnimateKey] = useState(location.pathname);
  const [fadeIn, setFadeIn] = useState(true);

  useEffect(() => {
    setFadeIn(false);
    const t = window.setTimeout(() => {
      setAnimateKey(location.pathname);
      setFadeIn(true);
    }, 50);
    return () => window.clearTimeout(t);
  }, [location.pathname]);

  const handleReset = () => {
    setRetryKey((k) => k + 1);
  };

  return (
    <ErrorBoundary
      key={`${location.pathname}-${retryKey}`}
      FallbackComponent={({ error, resetErrorBoundary }) => (
        <PageErrorFallback
          error={error instanceof Error ? error : new Error(String(error))}
          resetErrorBoundary={() => {
            handleReset();
            resetErrorBoundary();
          }}
        />
      )}
      onError={(error) => {
        logger.error('页面渲染错误:', String(error));
      }}
    >
      <div
        key={animateKey}
        className="transition-opacity duration-200 ease-out"
        style={{ opacity: fadeIn ? 1 : 0, transform: fadeIn ? 'translateY(0)' : 'translateY(8px)' }}
      >
        <TimedSuspense>{children}</TimedSuspense>
      </div>
    </ErrorBoundary>
  );
}

// 工具：包装 lazy import
export function withLazyPage(Comp: ComponentType) {
  return (
    <LazyRouteWrapper>
      <Comp />
    </LazyRouteWrapper>
  );
}
