import { useState, useEffect, useCallback, useRef } from 'react';
import { scopedStorage, logger } from '@lark-apaas/client-toolkit-lite';
import api from '@/lib/api';
import { useAuth } from './useAuth';
import type { Season } from '@/lib/theme';

// 数据同步状态
export type SyncStatus = 'idle' | 'syncing' | 'synced' | 'error';

interface UserDataPayload {
  themePreference: Season | 'auto';
  checkins: string[];
  streakDays: number;
  todos: Record<string, { items: any[]; version: number }>; // key: date
  notes: any[];
  monthlyReviews: Record<string, any>; // key: YYYY-MM
}

const THEME_KEY = 'seasonal-theme-override';
const CHECKINS_KEY = 'checkIns';
const NOTES_KEY = 'inspiration-notes';
const REVIEW_PREFIX = 'monthly-review:';
const TODOS_PREFIX = 'todos:';
const TODOS_VERSION_PREFIX = 'todos-version:';

function readAllLocal(): Partial<UserDataPayload> {
  const data: Partial<UserDataPayload> = {};
  try {
    // 主题
    const theme = scopedStorage.getItem(THEME_KEY);
    if (theme) data.themePreference = theme as Season | 'auto';

    // 签到
    const checkinsStr = scopedStorage.getItem(CHECKINS_KEY);
    if (checkinsStr) {
      try { data.checkins = JSON.parse(checkinsStr); } catch { /* noop */ }
    }

    // 随笔
    const notesStr = scopedStorage.getItem(NOTES_KEY);
    if (notesStr) {
      try { data.notes = JSON.parse(notesStr); } catch { /* noop */ }
    }

    // 待办 —— 扫描所有日期
    const todos: Record<string, { items: any[]; version: number }> = {};
    const keys = Object.keys(localStorage);
    const appPrefix = scopedStoragePrefix();
    for (const k of keys) {
      const cleanKey = appPrefix ? k.replace(appPrefix, '') : k;
      if (cleanKey.startsWith(TODOS_PREFIX) && !cleanKey.startsWith(TODOS_VERSION_PREFIX)) {
        const dateKey = cleanKey.slice(TODOS_PREFIX.length);
        const itemsStr = scopedStorage.getItem(cleanKey);
        const verStr = scopedStorage.getItem(`${TODOS_VERSION_PREFIX}${dateKey}`);
        if (itemsStr) {
          try {
          todos[dateKey] = {
            items: JSON.parse(itemsStr),
            version: verStr ? Number(verStr) : 0,
          };
        } catch { /* noop */ }
      }
    }
  }
  if (Object.keys(todos).length > 0) data.todos = todos;

  // 月度复盘
  const reviews: Record<string, any> = {};
  for (const k of keys) {
    const cleanKey = appPrefix ? k.replace(appPrefix, '') : k;
    if (cleanKey.startsWith(REVIEW_PREFIX)) {
      const monthKey = cleanKey.slice(REVIEW_PREFIX.length);
      const val = scopedStorage.getItem(cleanKey);
      if (val) {
        try { reviews[monthKey] = JSON.parse(val); } catch { /* noop */ }
      }
    }
  }
  if (Object.keys(reviews).length > 0) data.monthlyReviews = reviews;

  // 连续打卡天数
  if (data.checkins) {
    let streak = 0;
    const d = new Date();
    for (;;) {
      const key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
      if (data.checkins.includes(key)) {
        streak++;
        d.setDate(d.getDate() - 1);
      } else break;
    }
    data.streakDays = streak;
  }
  } catch {
    /* localStorage 损坏时返回空数据，不崩 */
    return {};
  }

  return data;
}

// 简易获取 scopedStorage 前缀
function scopedStoragePrefix(): string {
  // scopedStorage 内部会按 appId 加前缀，这里不直接读 key
  // 用 localStorage 兜底扫
  return '';
}

function writeAllToLocal(data: Partial<UserDataPayload>) {
  if (data.themePreference) {
    scopedStorage.setItem(THEME_KEY, data.themePreference);
  }
  if (data.checkins) {
    scopedStorage.setItem(CHECKINS_KEY, JSON.stringify(data.checkins));
  }
  if (data.notes) {
    scopedStorage.setItem(NOTES_KEY, JSON.stringify(data.notes));
  }
  if (data.todos) {
    for (const [date, val] of Object.entries(data.todos)) {
      scopedStorage.setItem(`${TODOS_PREFIX}${date}`, JSON.stringify(val.items));
      scopedStorage.setItem(`${TODOS_VERSION_PREFIX}${date}`, String(val.version));
    }
  }
  if (data.monthlyReviews) {
    for (const [month, val] of Object.entries(data.monthlyReviews)) {
      scopedStorage.setItem(`${REVIEW_PREFIX}${month}`, JSON.stringify(val));
    }
  }
}

interface UseDataSyncOptions {
  onNewDevice?: () => void;
}

export function useDataSync({ onNewDevice }: UseDataSyncOptions = {}) {
  const { isLoggedIn, user, token } = useAuth();
  const [syncStatus, setSyncStatus] = useState<SyncStatus>('idle');
  const [isNewDevice, setIsNewDevice] = useState(false);
  const initializedRef = useRef(false);

  // 登录后拉取云端数据 + 合并上传
  useEffect(() => {
    if (!isLoggedIn || !token || initializedRef.current) return;
    initializedRef.current = true;

    async function initSync() {
      setSyncStatus('syncing');
      try {
        const res = await api.get('/user/data');
        const cloud = (res.data as any).data || {};

        // 读取本地
        const local = readAllLocal();

        // 简单合并策略：两边都有数据时，取内容更长/更多的那一方
        const merged: Partial<UserDataPayload> = { ...cloud };

        // 主题：本地优先（尊重用户最近一次选择）
        if (local.themePreference) merged.themePreference = local.themePreference;

        // 签到：合并去重
        const localCheckins = local.checkins || [];
        const cloudCheckins: string[] = Array.isArray(cloud.checkins) ? cloud.checkins : [];
        merged.checkins = Array.from(new Set([...cloudCheckins, ...localCheckins])).sort();
        merged.streakDays = Math.max(cloud.streak_days || 0, local.streakDays || 0);

        // 待办：按日期合并，有数据就保留
        const localTodos = local.todos || {};
        const cloudTodos = cloud.todos && typeof cloud.todos === 'object' ? cloud.todos : {};
        const allTodoDates = new Set([...Object.keys(localTodos), ...Object.keys(cloudTodos)]);
        const mergedTodos: Record<string, { items: any[]; version: number }> = {};
        for (const date of allTodoDates) {
          const l = localTodos[date];
          const c = cloudTodos[date];
          if (l && c) {
            // 选数量多的
            mergedTodos[date] = (l.items?.length || 0) >= (c.items?.length || 0) ? l : c;
          } else {
            mergedTodos[date] = l || c;
          }
        }
        merged.todos = mergedTodos;

        // 随笔：合并去重（按 id）
        const localNotes = local.notes || [];
        const cloudNotes = Array.isArray(cloud.notes) ? cloud.notes : [];
        const noteMap = new Map<string, any>();
        for (const n of [...cloudNotes, ...localNotes]) {
          if (n?.id) noteMap.set(n.id, n);
        }
        merged.notes = Array.from(noteMap.values());

        // 月度复盘：按月合并
        const localRev = local.monthlyReviews || {};
        const cloudRev = cloud.monthly_reviews && typeof cloud.monthly_reviews === 'object'
          ? cloud.monthly_reviews
          : (cloud.monthlyReviews && typeof cloud.monthlyReviews === 'object' ? cloud.monthlyReviews : {});
        merged.monthlyReviews = { ...cloudRev, ...localRev };

        // 写入本地（覆盖）
        writeAllToLocal(merged);

        // 上传合并结果
        await api.put('/user/data', {
          themePreference: merged.themePreference,
          checkins: merged.checkins,
          streakDays: merged.streakDays,
          todos: merged.todos,
          notes: merged.notes,
          monthlyReviews: merged.monthlyReviews,
        });

        // 检查是否新设备
        if (user && (user as any).last_device_fingerprint) {
          // 前端无法准确判断，靠登录返回的 reason 字段
          const lastReason = scopedStorage.getItem('last_login_reason');
          if (lastReason && lastReason.includes('新设备')) {
            setIsNewDevice(true);
            onNewDevice?.();
          }
        }

        setSyncStatus('synced');
        setTimeout(() => setSyncStatus('idle'), 3000);
      } catch (err: any) {
        logger.error('[sync] 初始化同步失败', String(err.message || err));
        setSyncStatus('error');
        // 401 通常是 token 失效，不阻断用户
      }
    }

    initSync();
  }, [isLoggedIn, token, user, onNewDevice]);

  // 登出重置
  useEffect(() => {
    if (!isLoggedIn) {
      initializedRef.current = false;
      setSyncStatus('idle');
      setIsNewDevice(false);
    }
  }, [isLoggedIn]);

  // 手动触发保存（用于操作时实时同步）
  const saveToCloud = useCallback(async (patch: Partial<UserDataPayload>) => {
    if (!isLoggedIn || !token) return;
    try {
      setSyncStatus('syncing');
      await api.put('/user/data', patch);
      setSyncStatus('synced');
      setTimeout(() => setSyncStatus('idle'), 2000);
    } catch (err: any) {
      logger.error('[sync] 保存失败', String(err.message || err));
      setSyncStatus('error');
      setTimeout(() => setSyncStatus('idle'), 3000);
    }
  }, [isLoggedIn, token]);

  const dismissNewDevice = useCallback(() => {
    setIsNewDevice(false);
    scopedStorage.removeItem('last_login_reason');
  }, []);

  return {
    syncStatus,
    isNewDevice,
    dismissNewDevice,
    saveToCloud,
  };
}
