import { createContext, useContext, useState, useEffect, useCallback, useRef, type ReactNode } from 'react';
import { scopedStorage, logger } from '@lark-apaas/client-toolkit-lite';
import { toast } from 'sonner';
import api from '@/lib/api';
import { useAuth } from './useAuth';

// 共享数据模块对应的 storage key
export const SHARED_KEYS = {
  purchaseOrders: 'purchase_orders_v2',
  leadTimeRecords: 'purchase-leadtime-records',
  logisticsConfig: 'logistics_config_v1',
  commonShops: 'purchase_common_shops_v1',
  viralShortsImages: 'script-generator-images',
  inspirationNotes: 'inspiration-notes',
  aiTips: 'ai-tips-data',
  operationNotes: 'note:operation',
} as const;

// 后端字段名（snake_case）
const CLOUD_FIELDS = {
  purchaseOrders: 'purchase_orders',
  leadTimeRecords: 'lead_time_records',
  logisticsConfig: 'logistics_config',
  commonShops: 'common_shops',
  viralShortsImages: 'viral_shorts_images',
  inspirationNotes: 'inspiration_notes',
  aiTips: 'ai_tips',
  operationNotes: 'operation_notes',
} as const;

export type SharedModule = keyof typeof SHARED_KEYS;

interface SharedDataContextValue {
  isReady: boolean;
  isSyncing: boolean;
  // 上次云端同步时间戳（页面可监听此值判断是否有新数据）
  lastSyncAt: number;
  // 触发拉取（登录后调用）
  pullSharedData: () => Promise<void>;
  // 某个模块变化时推送到云端
  pushModule: (module: SharedModule, data: any) => Promise<void>;
  // 立即推送（跳过防抖，用于状态推进等关键操作）
  pushModuleImmediate: (module: SharedModule, data: any) => Promise<void>;
  // 强制全量同步
  syncAll: () => Promise<void>;
}

const SharedDataContext = createContext<SharedDataContextValue | null>(null);

export function SharedDataProvider({ children }: { children: ReactNode }) {
  const { isLoggedIn, token } = useAuth();
  const [isReady, setIsReady] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [lastSyncAt, setLastSyncAt] = useState(0);
  const pushTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const pendingPushRef = useRef<Partial<Record<SharedModule, any>>>({});
  const pushScheduledRef = useRef(false);

  // 旧版本 key → 新 key 的迁移映射（仅迁移一次，迁移后删除旧 key）
  const LEGACY_KEY_MAP: Record<string, string> = {
    purchase_orders: SHARED_KEYS.purchaseOrders,
    leadtime_records: SHARED_KEYS.leadTimeRecords,
    logistics_config: SHARED_KEYS.logisticsConfig,
    common_shops: SHARED_KEYS.commonShops,
  };

  // 登录后先做一次旧 key 迁移 + 过期清理，再拉取云端
  useEffect(() => {
    if (!isLoggedIn || !token) return;
    try {
      let migrated = false;
      for (const [oldKey, newKey] of Object.entries(LEGACY_KEY_MAP)) {
        const raw = scopedStorage.getItem(oldKey);
        if (raw && !scopedStorage.getItem(newKey)) {
          scopedStorage.setItem(newKey, raw);
          migrated = true;
          logger.info(`[shared] 迁移旧 key ${oldKey} → ${newKey}`);
        }
        // 无论是否迁移过，都删除旧 key 释放空间
        scopedStorage.removeItem(oldKey);
      }
      // 删除已知的历史废弃 key
      scopedStorage.removeItem('crossborder_orders_v1');
      scopedStorage.removeItem('purchase_orders_v1');
      if (migrated) {
        logger.info('[shared] 旧版本数据迁移完成');
      }
    } catch (err) {
      logger.error('[shared] 迁移旧数据失败:', String(err));
    }
  }, [isLoggedIn, token]);

  // 从云端拉取共享数据，按 updated_at 逐条合并（本地新的保留，云端新的才覆盖）
  const pullSharedData = useCallback(async () => {
    if (!isLoggedIn || !token) return;
    try {
      setIsSyncing(true);
      const res = await api.get('/shared/data');
      const cloud = (res.data as any).data || {};

      // 后端 snake_case → 前端 storage key
      const keyMap: Record<string, string> = {
        [CLOUD_FIELDS.purchaseOrders]: SHARED_KEYS.purchaseOrders,
        [CLOUD_FIELDS.leadTimeRecords]: SHARED_KEYS.leadTimeRecords,
        [CLOUD_FIELDS.logisticsConfig]: SHARED_KEYS.logisticsConfig,
        [CLOUD_FIELDS.commonShops]: SHARED_KEYS.commonShops,
        [CLOUD_FIELDS.viralShortsImages]: SHARED_KEYS.viralShortsImages,
        [CLOUD_FIELDS.inspirationNotes]: SHARED_KEYS.inspirationNotes,
        [CLOUD_FIELDS.aiTips]: SHARED_KEYS.aiTips,
      };

      let mergedCount = 0;
      for (const [cloudField, storageKey] of Object.entries(keyMap)) {
        const cloudVal = cloud[cloudField];
        if (cloudVal === undefined || cloudVal === null) continue;

        // 只处理数组类型（订单、记录等），按 id + updated_at 合并
        const localRaw = scopedStorage.getItem(storageKey);
        let localData: any[] = [];
        if (localRaw) {
          try { localData = JSON.parse(localRaw); } catch { localData = []; }
        }

        if (Array.isArray(cloudVal) && Array.isArray(localData)) {
          // 按 id 索引本地数据
          const localMap = new Map<string, any>();
          for (const item of localData) {
            if (item?.id) localMap.set(String(item.id), item);
          }

          // 遍历云端数据：云端更新时间新 → 覆盖；本地新 → 保留
          for (const cloudItem of cloudVal) {
            if (!cloudItem?.id) continue;
            const cid = String(cloudItem.id);
            const localItem = localMap.get(cid);
            const cloudTime = new Date(cloudItem.updated_at || cloudItem.updatedAt || 0).getTime();
            const localTime = new Date(localItem?.updated_at || localItem?.updatedAt || 0).getTime();

            if (!localItem || cloudTime >= localTime) {
              localMap.set(cid, cloudItem);
              mergedCount++;
            }
            // 本地更新 → 保留本地（不覆盖）
          }

          const merged = Array.from(localMap.values());
          scopedStorage.setItem(storageKey, JSON.stringify(merged));
          logger.info(`[shared] 合并 ${cloudField}: 本地${localData.length}条 + 云端${cloudVal.length}条 → 合并后${merged.length}条（云端覆盖${mergedCount}条）`);
        } else if (typeof cloudVal === 'string' && cloudVal) {
          // 字符串类型直接覆盖（简单配置）
          scopedStorage.setItem(storageKey, cloudVal);
        } else if (typeof cloudVal === 'object' && !Array.isArray(cloudVal) && Object.keys(cloudVal).length > 0) {
          // 对象类型：浅合并
          const localObj = localRaw ? (() => { try { return JSON.parse(localRaw); } catch { return {}; } })() : {};
          const merged = { ...localObj, ...cloudVal };
          scopedStorage.setItem(storageKey, JSON.stringify(merged));
        }
      }

      setIsReady(true);
      setLastSyncAt(Date.now());
      logger.info(`[shared] 拉取共享数据成功，合并 ${mergedCount} 条云端更新`);
    } catch (err: any) {
      logger.error('[shared] 拉取共享数据失败', String(err.message || err));
      // 拉取失败也标记 ready，使用本地数据继续工作
      setIsReady(true);
    } finally {
      setIsSyncing(false);
    }
  }, [isLoggedIn, token]);

  // 批量推送：合并 500ms 内的多次改动，一次 PUT
  // 失败时自动重试最多 3 次
  const flushPendingPush = useCallback(async () => {
    if (!isLoggedIn || !token) return;
    const pending = pendingPushRef.current;
    pendingPushRef.current = {};
    pushScheduledRef.current = false;

    if (Object.keys(pending).length === 0) return;

    // 转成后端 snake_case
    const body: Record<string, any> = {};
    for (const [mod, data] of Object.entries(pending) as [SharedModule, any][]) {
      const cloudField = CLOUD_FIELDS[mod];
      if (!cloudField) continue;
      // 空数组不推送，防止覆盖云端已有数据（安全守卫）
      if (Array.isArray(data) && data.length === 0) continue;
      body[cloudField] = data;
    }

    const fieldCount = Object.keys(body).length;
    const itemCounts = Object.entries(body).map(([k, v]) => `${k}:${Array.isArray(v) ? v.length : 'obj'}`).join(', ');
    logger.info(`[shared] 推送 ${fieldCount} 个字段 (${itemCounts})`);

    const MAX_RETRY = 2;
    let lastErr: any = null;
    let hasShownError = false;

    for (let attempt = 1; attempt <= MAX_RETRY; attempt++) {
      try {
        setIsSyncing(true);
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 10000);
        try {
          await api.post('/shared/data', body, { signal: controller.signal });
        } finally {
          clearTimeout(timeoutId);
        }
        logger.info(`[shared] 推送成功（第${attempt}次尝试）`);
        return;
      } catch (err: any) {
        lastErr = err;
        const isTimeout = err?.name === 'CanceledError' || err?.code === 'ERR_CANCELED' || err?.message?.includes('timeout');
        logger.warn(`[shared] 推送失败（第${attempt}/${MAX_RETRY}次）${isTimeout ? '(超时)' : ''}:`, String(err.message || err));
        if (attempt < MAX_RETRY) {
          await new Promise((r) => setTimeout(r, 800));
        } else if (!hasShownError) {
          hasShownError = true;
          toast.error('数据保存失败，请检查网络');
        }
      } finally {
        setIsSyncing(false);
      }
    }

    // 全部重试失败：把数据放回待推队列，下次再试
    logger.error('[shared] 推送最终失败，已放回待推队列');
    for (const [mod, data] of Object.entries(pending) as [SharedModule, any][]) {
      // 只保留最新版本（如果期间有新数据则不覆盖）
      if (!(mod in pendingPushRef.current)) {
        pendingPushRef.current[mod] = data;
      }
    }
    // 标记下次 flush 前有积压
  }, [isLoggedIn, token]);

  const pushModule = useCallback(async (module: SharedModule, data: any) => {
    if (!isLoggedIn || !token) return;
    // 合并到待推队列
    pendingPushRef.current[module] = data;

    if (!pushScheduledRef.current) {
      pushScheduledRef.current = true;
      pushTimerRef.current = setTimeout(() => {
        pushTimerRef.current = null;
        flushPendingPush();
      }, 500);
    }
  }, [isLoggedIn, token, flushPendingPush]);

  // 立即推送（跳过防抖，用于状态推进等关键操作）
  const pushModuleImmediate = useCallback(async (module: SharedModule, data: any) => {
    if (!isLoggedIn || !token) return;
    // 先把数据写进 pending（保证即使失败也能被后续 flush 捡起来）
    pendingPushRef.current[module] = data;
    // 取消已有定时器
    if (pushTimerRef.current) {
      clearTimeout(pushTimerRef.current);
      pushTimerRef.current = null;
    }
    pushScheduledRef.current = false;
    // 立即 flush
    await flushPendingPush();
  }, [isLoggedIn, token, flushPendingPush]);

  const syncAll = useCallback(async () => {
    if (!isLoggedIn || !token) return;
    // 把本地所有共享数据全量推上去
    const payload: Record<string, any> = {};
    for (const [mod, storageKey] of Object.entries(SHARED_KEYS) as [SharedModule, string][]) {
      const raw = scopedStorage.getItem(storageKey);
      if (raw) {
        try {
          const parsed = JSON.parse(raw);
          // 【安全】空数组不推送，防止全量同步时用空数组覆盖云端真实数据
          if (Array.isArray(parsed) && parsed.length === 0) continue;
          payload[CLOUD_FIELDS[mod]] = parsed;
        } catch {
          // 忽略解析失败
        }
      }
    }
    logger.info(`[shared] 全量同步 ${Object.keys(payload).length} 个字段`);
      try {
        setIsSyncing(true);
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 15000);
        try {
          await api.post('/shared/data', payload, { signal: controller.signal });
        } finally {
          clearTimeout(timeoutId);
        }
        logger.info('[shared] 全量同步成功');
      } catch (err: any) {
        logger.error('[shared] 全量同步失败', String(err.message || err));
        toast.error('数据保存失败，请检查网络');
        throw err;
      } finally {
        setIsSyncing(false);
      }
  }, [isLoggedIn, token]);

  // 登录后拉取一次
  useEffect(() => {
    if (!isLoggedIn || !token) {
      setIsReady(false);
      return;
    }
    pullSharedData();
  }, [isLoggedIn, token, pullSharedData]);

  // 每 30 秒轮询一次，保持多端实时性（轻量）
  // 页面后台时完全停止定时器，回到前台立即补一次再继续轮询
  useEffect(() => {
    if (!isLoggedIn || !token) return;

    let intervalId: ReturnType<typeof setInterval> | null = null;

    function startPolling() {
      if (intervalId) return;
      intervalId = setInterval(() => {
        pullSharedData();
      }, 30000);
    }

    function stopPolling() {
      if (intervalId) {
        clearInterval(intervalId);
        intervalId = null;
      }
    }

    function handleVisibility() {
      if (document.visibilityState === 'visible') {
        // 回到前台：先立刻拉一次，再启动轮询
        pullSharedData();
        startPolling();
      } else {
        stopPolling();
      }
    }

    // 仅前台时启动轮询
    if (typeof document !== 'undefined' && document.visibilityState === 'visible') {
      startPolling();
    }

    document.addEventListener('visibilitychange', handleVisibility);
    return () => {
      document.removeEventListener('visibilitychange', handleVisibility);
      stopPolling();
      if (pushTimerRef.current) {
        clearTimeout(pushTimerRef.current);
        pushTimerRef.current = null;
      }
      pushScheduledRef.current = false;
      pendingPushRef.current = {};
    };
  }, [isLoggedIn, token, pullSharedData]);

  // 页面卸载前强制 flush 待推数据（同步 XHR 兜底）
  useEffect(() => {
    if (!isLoggedIn || !token) return;

    function handleBeforeUnload() {
      if (pushScheduledRef.current && Object.keys(pendingPushRef.current).length > 0) {
        // 取消定时器，直接同步发送（用 sendBeacon 或同步 XHR）
        if (pushTimerRef.current) {
          clearTimeout(pushTimerRef.current);
          pushTimerRef.current = null;
        }
        const pending = pendingPushRef.current;
        pendingPushRef.current = {};
        pushScheduledRef.current = false;

        const body: Record<string, any> = {};
        for (const [mod, data] of Object.entries(pending) as [SharedModule, any][]) {
          const cloudField = CLOUD_FIELDS[mod];
          if (!cloudField) continue;
          // 【安全】空数组不推送，防止卸载时用空数组覆盖云端真实数据
          if (Array.isArray(data) && data.length === 0) continue;
          body[cloudField] = data;
        }

        try {
          // sendBeacon 在页面卸载时最可靠
          const blob = new Blob([JSON.stringify(body)], { type: 'application/json' });
          const ok = navigator.sendBeacon('/api/shared/data', blob);
          logger.info(`[shared] 卸载前推送 ${Object.keys(body).length} 字段，sendBeacon=${ok}`);
        } catch (e) {
          logger.error('[shared] 卸载前推送失败:', String(e));
        }
      }
    }

    window.addEventListener('beforeunload', handleBeforeUnload);
    return () => window.removeEventListener('beforeunload', handleBeforeUnload);
  }, [isLoggedIn, token]);

  return (
    <SharedDataContext.Provider value={{ isReady, isSyncing, lastSyncAt, pullSharedData, pushModule, pushModuleImmediate, syncAll }}>
      {children}
    </SharedDataContext.Provider>
  );
}

export function useSharedData() {
  const ctx = useContext(SharedDataContext);
  if (!ctx) {
    throw new Error('useSharedData must be used within SharedDataProvider');
  }
  return ctx;
}
